<script setup>
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import DataFilters from './DataFilters.vue'
import { outputCatalogue,buildOutput } from '../../data/catalogue.js'
import { downloadCSV,downloadXLSX,downloadGeoJSON,printReport } from '../../lib/exports.js'
import { buildMAICSections,selectReportRevision } from './reportLogic.js'
const store=useDemo(),route=useRoute(),router=useRouter(),q=useQuasar(),search=ref(''),group=ref('All'),asOf=ref(new Date().toISOString().slice(0,10)),eventId=ref(''),previewJob=ref(null),snapshotOpen=ref(false),busy=ref(false),error=ref(''),template=ref('Demonstration v1'),note=ref('')
const history=computed(()=>route.path==='/admin/exports'),builder=computed(()=>!!route.params.outputId),output=computed(()=>outputCatalogue.find(o=>o.id===route.params.outputId))
const selection=computed({get:()=>store.state.selection,set:v=>{store.state.selection=v;store.persist()}})
const filtered=computed(()=>store.selectEvents(selection.value)),documentOutput=computed(()=>['O15','O16','O17','O18'].includes(output.value?.id))
const population=computed(()=>documentOutput.value?(eventId.value?filtered.value.filter(e=>e.id===eventId.value):filtered.value.slice(0,1)):filtered.value)
const documentRevisions=computed(()=>{if(!documentOutput.value)return[];const type={O16:'1B',O17:'2',O18:'3B'}[output.value.id]||'spot';return population.value.map(event=>{const report=store.state.reports.filter(r=>r.eventId===event.id&&r.type===type&&(!asOf.value||!r.date||r.date<=asOf.value)).sort((a,b)=>(Number(b.revision)||0)-(Number(a.revision)||0))[0];return selectReportRevision({event,report,evidenceRecords:store.state.evidence})})})
const outputPopulation=computed(()=>output.value?.id==='O15'?documentRevisions.value.map(item=>item.event):population.value)
const rows=computed(()=>output.value?buildOutput(output.value.id,outputPopulation.value,{cases:store.state.cases,reports:store.state.reports,imports:store.visibleRecords('imports')},{...selection.value,asOf:asOf.value}):[])
const columns=computed(()=>[...new Set(rows.value.flatMap(row=>Object.keys(row)))].map(field=>({name:field,label:field,field:r=>r[field] == null || r[field]===''?'Unknown':typeof r[field]==='object'?JSON.stringify(r[field]):r[field],align:'left',sortable:true})))
const visibleCatalogue=computed(()=>outputCatalogue.filter(o=>(group.value==='All'||o.group===group.value)&&`${o.id} ${o.title}`.toLowerCase().includes(search.value.toLowerCase())))
const groups=computed(()=>['All',...new Set(outputCatalogue.map(o=>o.group))])
const exportHistory=computed(()=>store.visibleRecords('exports'))
watch(exportHistory,records=>{if(previewJob.value&&!records.some(record=>record.id===previewJob.value.id)){previewJob.value=null;snapshotOpen.value=false}})
const sections=computed(()=>{
 if(!documentOutput.value)return [{title:'Source and counting notes',content:output.value?.notes},{title:'Template status',content:'Structured demonstration. Official paper size, signatory and editable master remain for MARINA confirmation. Form 1A is template-required; no Form 1A document is generated.'}]
 const revision=documentRevisions.value[0];if(!revision)return[]
 const {event:e,report,evidence}=revision
 const type={O16:'1B',O17:'2',O18:'3B'}[output.value.id]||'spot'
 const preparedBy=report?.preparedBy||store.state.users.find(u=>u.id===e.ownerId)?.name
 if(type!=='spot')return buildMAICSections({type,event:e,report,asOf:asOf.value,preparedBy,evidence})
 return [
  {title:'Occurrence and source',content:`Reference: ${e.ref}\nOccurrence: ${e.dateUnknown?'Unknown date':e.date||'Unknown date'} ${e.timeUnknown?'Unknown time':e.time||'Unknown time'}\nPlace: ${e.place||'Unknown'}\n${e.summary||'Unknown'}\nSource: ${e.sourceType||'Unknown'} · ${e.sourceRef||'Unknown'}`},
  {title:'Involved vessels',content:(e.vessels||[]).map(v=>`${v.name} · ${v.type||'Unknown service'} · Official ${v.officialNumber||'Unknown'} · IMO ${v.imoNumber||'Unknown'} · GT ${v.grossTonnage??'Unknown'} · Owner ${v.owner||'Unknown'} · Operator ${v.operator||'Unknown'}`).join('\n')},
  {title:'Human and vessel consequences',content:JSON.stringify(e.consequences,(_key,value)=>value==null?'Unknown':value,2)},
  {title:'Initial actions',content:e.initialActions||'Unknown'},
  {title:'Recommendations',content:e.recommendations||'Unknown'},
  {title:'Prepared by / submitting office',content:`Prepared by: ${preparedBy||'Unknown'}\nOffice: ${e.officeId||'Unknown'}\nRevision: ${report?.revision??'No saved report revision'}`},
  {title:'Preserved spot fields and evidence appendix',content:JSON.stringify({fields:report?.fields||{},evidence},(_key,value)=>value==null?'Unknown':value,2)}
 ]
})
function snapshot(){return {title:output.value.title,subtitle:`${output.value.id} · ${template.value} · Fictional demonstration`,rows:JSON.parse(JSON.stringify(rows.value)),sections:JSON.parse(JSON.stringify(sections.value)),metadata:{'Output family':output.value.id,'Counting grain':output.value.grain,'Selected events':population.value.length,'Vessel involvements':outputPopulation.value.reduce((s,e)=>s+(e.vessels?.length||0),0),'As of':asOf.value,Selection:JSON.stringify(selection.value),Template:template.value,Notes:note.value||output.value.notes},events:JSON.parse(JSON.stringify(outputPopulation.value))}}
function svgFor(snap){const values=snap.rows.slice(0,16).map(r=>({label:r.Category || r.Reference || 'Event',value:Number(r.Total??r.Count??r.Events??1)})); const max=Math.max(1,...values.map(r=>r.value)),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return `<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="${150+values.length*36}" viewBox="0 0 1100 ${150+values.length*36}"><rect width="100%" height="100%" fill="white"/><g font-family="Arial" fill="#1a365d"><text x="24" y="32" font-size="21">${esc(snap.title)}</text><text x="24" y="58" font-size="12">Fictional demonstration · ${esc(snap.metadata['As of'])} · ${esc(snap.metadata['Counting grain'])} · Full table supplied separately</text>${values.map((r,i)=>`<text x="24" y="${100+i*36}" font-size="12">${esc(r.label)}</text><rect x="270" y="${84+i*36}" width="${r.value/max*720}" height="24" fill="#2b6cb0"/><text x="${1000}" y="${100+i*36}" font-size="12">${r.value}</text>`).join('')}</g></svg>`}
const figure=computed(()=>output.value?.id==='O21'?`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgFor(snapshot()))}`:'')
async function deliver(format,snap,id){
 const filename=`${id || 'snapshot'}-${snap.metadata?.['As of'] || asOf.value}`
 if(format==='CSV')downloadCSV(`${filename}.csv`,snap.rows)
 else if(format==='XLSX')await downloadXLSX(`${filename}.xlsx`,[{name:'Output',rows:snap.rows},{name:'Selection and method',rows:Object.entries(snap.metadata).map(([Field,Value])=>({Field,Value}))},{name:'Narrative sections',rows:snap.sections.map(s=>({Section:s.title,Content:s.content}))}])
 else if(format==='GeoJSON')downloadGeoJSON(`${filename}.geojson`,snap.events)
 else if(format==='SVG'){const blob=new Blob([svgFor(snap)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${filename}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
 else printReport(snap)
}
async function generate(format){if(!store.can('export'))return;busy.value=true;error.value='';try{const snap=snapshot();await deliver(format,snap,output.value.id);const record=store.recordExport({name:output.value.title,outputId:output.value.id,format,status:'ready',selection:{...selection.value,asOf:asOf.value,eventId:eventId.value},snapshot:snap,createdAt:new Date().toISOString(),createdBy:store.currentUser.value.id,revision:exportHistory.value.filter(j=>j.outputId===output.value.id).length+1,notes:note.value});q.notify({type:'positive',message:`Revision ${record.revision} saved to local output history.`})}catch(e){error.value=e.message}finally{busy.value=false}}
function authorizedExport(job){const record=store.visibleRecords('exports').find(item=>item.id===job?.id);if(!record||!store.can('export'))throw new Error('This output is unavailable in your current account scope.');return record}
function reopen(job){try{previewJob.value=authorizedExport(job);snapshotOpen.value=true}catch(e){previewJob.value=null;snapshotOpen.value=false;q.notify({type:'negative',message:e.message})}}
async function redownload(job,format){try{const record=authorizedExport(job),snap=record.snapshot;if(!snap?.rows)throw new Error('This older sample job has no retained table. Rebuild its output family to create a complete snapshot.');await deliver(format || record.format,snap,record.outputId)}catch(e){q.notify({type:'negative',message:e.message})}}
const jobColumns=[{name:'name',label:'Output / snapshot',field:'name',align:'left'},{name:'outputId',label:'Family',field:'outputId'},{name:'revision',label:'Revision',field:'revision'},{name:'format',label:'Format',field:'format'},{name:'createdAt',label:'Created',field:r=>r.createdAt?new Date(r.createdAt).toLocaleString():'Unknown'},{name:'status',label:'Status',field:'status'},{name:'action',label:'Artifact',field:'id'}]
</script>
<template>
 <div class="page-wrap">
 <PageHeader :title="history?'Export and issued history':builder?(output?.title || 'Output unavailable'):'Report catalogue'" :subtitle="history?'Retained browser-local snapshots preserve the filters, rows and revision used to generate each artifact.':builder?'Preview the complete selected population, keep unknown values and generate a reproducible artifact.':'All 22 audited output families from one shared event, vessel, investigation and enforcement model.'" eyebrow="REPORTING DESK"><template #actions><q-btn v-if="builder||history" no-caps outline icon="apps" label="Catalogue" to="/admin/reports" /><q-btn v-if="!history" no-caps outline icon="history" label="Output history" to="/admin/exports" /></template></PageHeader>
 <q-banner v-if="error" rounded class="bg-red-1 text-negative q-mb-md">{{error}}</q-banner>
 <template v-if="!builder&&!history"><div class="toolbar-row q-mb-lg"><q-input v-model="search" outlined dense clearable label="Search all 22 families" style="min-width:260px"><template #prepend><q-icon name="search" /></template></q-input><q-select v-model="group" outlined dense :options="groups" label="Output group" style="min-width:250px" /><q-chip color="blue-1" text-color="primary">{{visibleCatalogue.length}} / 22 output families</q-chip></div><div class="catalogue-grid"><div v-for="item in visibleCatalogue" :key="item.id" class="panel catalogue-card"><div class="row justify-between items-center"><span class="eyebrow">{{item.id}} · {{item.group}}</span><q-icon :name="item.group==='MAIC documents'?'description':item.group==='Maps and quality'?'map':'table_chart'" color="primary" size="24px" /></div><h2 class="section-title q-mt-md">{{item.title}}</h2><p class="muted">{{item.notes}}</p><div class="q-mt-auto"><p class="text-caption">Grain: {{item.grain}} · {{item.template}}</p><div class="row justify-between items-center"><span class="text-caption muted">{{item.formats.join(' · ')}}</span><q-btn no-caps color="primary" flat label="Build report" icon-right="arrow_forward" :to="`/admin/reports/build/${item.id}`" /></div></div></div></div><div class="panel q-mt-lg"><h2 class="section-title">Template coverage</h2><p>Form 1A remains template-required because no source layout was supplied. O16–O18 preserve structured MAIC sections and saved revisions. Official layout, signatories, paper size and detailed legacy column order require approved editable masters.</p></div></template>
 <template v-else-if="builder&&output"><DataFilters v-model="selection" /><div class="panel q-mb-lg"><div class="form-grid"><q-select v-if="documentOutput" v-model="eventId" outlined emit-value map-options :options="filtered.map(e=>({label:`${e.ref} · ${e.type}`,value:e.id}))" clearable label="Event (first matching if empty)" /><q-input v-model="asOf" type="date" outlined stack-label label="Observation / issue cutoff" /><q-select v-model="template" outlined :options="['Demonstration v1']" label="Template version" /><q-input v-model="note" outlined label="Selection / source note" /><q-select v-model="selection.homeport" outlined :options="['All',...new Set(store.visibleEvents.value.map(e=>e.homeport).filter(Boolean))]" label="Homeport office" @update:model-value="store.persist()" /><q-select v-model="selection.cpc" outlined :options="['All',...new Set(store.visibleEvents.value.map(e=>e.cpc).filter(Boolean))]" label="CPC office" @update:model-value="store.persist()" /><q-select v-model="selection.issuingOffice" outlined :options="['All',...new Set(store.visibleEvents.value.map(e=>e.issuingOffice).filter(Boolean))]" label="Actual issuing office" @update:model-value="store.persist()" /></div><div class="row q-gutter-sm items-center q-mt-lg"><q-chip color="blue-1" text-color="primary">{{population.length}} unique events</q-chip><q-chip>{{outputPopulation.reduce((s,e)=>s+(e.vessels?.length||0),0)}} involvements</q-chip><q-chip>{{rows.length}} output rows</q-chip><q-chip>Grain: {{output.grain}}</q-chip></div><p class="muted">{{output.notes}}</p><div class="q-gutter-sm"><q-btn v-for="format in output.formats" :key="format" no-caps :outline="format!=='PDF'" color="primary" :icon="format==='PDF'?'print':'download'" :label="format==='PDF'?'Print / Save as PDF':`Download ${format}`" :loading="busy" @click="generate(format)" /></div></div><div v-if="figure" class="panel q-mb-lg"><img :src="figure" alt="Selected incident type figure with underlying table below" class="figure-preview" /></div><div class="panel"><div class="row justify-between items-center"><h2 class="section-title">Population preview</h2><span class="muted text-caption">Downloads include all {{rows.length}} rows, across every page</span></div><q-table flat :rows="rows.map((r,i)=>({...r,_key:i}))" :columns="columns" row-key="_key" :pagination="{rowsPerPage:10}" :rows-per-page-options="[10,25,50,0]" wrap-cells class="preview-table"><template #no-data><div class="q-pa-lg full-width">No matching source records for this output. Adjust the selection or create the required case / report revision. An empty preview is retained as an explicit zero-record selection.</div></template></q-table></div><div class="panel q-mt-lg"><h2 class="section-title">Narrative and methodology preview</h2><q-expansion-item v-for="section in sections" :key="section.title" :label="section.title" default-opened header-class="text-primary"><p class="narrative q-pa-md">{{section.content}}</p></q-expansion-item></div></template>
 <div v-else-if="history" class="panel"><q-table flat :rows="exportHistory" :columns="jobColumns" row-key="id" :pagination="{rowsPerPage:10,sortBy:'createdAt',descending:true}" wrap-cells><template #body-cell-name="props"><q-td :props="props"><q-btn flat no-caps color="primary" :label="props.value" @click="reopen(props.row)" /></q-td></template><template #body-cell-status="props"><q-td :props="props"><StatusBadge :status="props.value" /></q-td></template><template #body-cell-action="props"><q-td :props="props"><div class="row no-wrap q-gutter-xs"><q-btn no-caps outline size="sm" icon="visibility" label="Snapshot" @click="reopen(props.row)" /><q-btn no-caps flat size="sm" icon="download" label="Download again" @click="redownload(props.row)" /></div></q-td></template><template #no-data><div class="q-pa-lg full-width">No outputs generated yet. Build any catalogue family to create a downloadable snapshot.</div></template></q-table><p class="muted">Jobs are simulated locally. Ready means the browser artifact was generated; no server queue, official release or signed document is implied.</p></div>
 <div v-else class="panel">This output family is unavailable. <router-link to="/admin/reports">Open catalogue</router-link>.</div>
 <q-dialog v-model="snapshotOpen"><q-card style="width:1000px;max-width:96vw"><q-card-section><h2 class="section-title">{{previewJob?.name}} · revision {{previewJob?.revision}}</h2><p class="muted">Created {{previewJob?.createdAt}} · {{previewJob?.format}} · {{previewJob?.snapshot?.rows?.length ?? 'Unknown'}} retained rows</p><pre class="metadata">{{previewJob?.snapshot?.metadata || previewJob?.selection}}</pre><q-table v-if="previewJob?.snapshot?.rows" flat :rows="previewJob.snapshot.rows.map((r,i)=>({...r,_key:i}))" :columns="Object.keys(previewJob.snapshot.rows[0]||{}).map(field=>({name:field,label:field,field:r=>r[field]??'Unknown',align:'left'}))" row-key="_key" :pagination="{rowsPerPage:5}" wrap-cells /></q-card-section><q-card-actions align="right"><q-btn v-close-popup no-caps flat label="Close" /><q-btn no-caps outline label="CSV from snapshot" @click="redownload(previewJob,'CSV')" /><q-btn no-caps color="primary" label="Print snapshot" @click="redownload(previewJob,'PDF')" /></q-card-actions></q-card></q-dialog>
 </div>
</template>
<style scoped>.catalogue-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.catalogue-card{display:flex;flex-direction:column;min-height:260px}.catalogue-card .section-title{font-size:18px}.preview-table :deep(td){min-width:120px;max-width:360px}.narrative{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.metadata{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.figure-preview{display:block;max-width:100%;max-height:600px}@media(max-width:1100px){.catalogue-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.catalogue-grid{grid-template-columns:1fr}}</style>
